package com.mohymods.kingdomsmp.economy;
import static org.junit.jupiter.api.Assertions.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import com.mohymods.kingdomsmp.profession.*;
import net.minecraft.nbt.*;
import java.nio.file.*;
import java.util.*;
import java.io.IOException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
/** Canonical model fixtures only. Actual current inventory/native costs/physical receipts are separate runtime tests. */
class ServiceWorkStoreTest {
 @TempDir Path directory;UUID smith,sourceStore=UUID.randomUUID();
 EconomyStore setup()throws Exception{var f=new SmithProgressStoreTest();f.directory=directory;var s=f.journeyman();smith=f.p;var pending=s.prepareProfessionDelivery(UUID.randomUUID(),smith,CraftDeliveryQuests.NETHERITE,"Pure model alloy prerequisite",CraftDeliveryQuests.defaults(CraftDeliveryQuests.NETHERITE));s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));var item=new CompoundTag();item.putString("id","minecraft:netherite_pickaxe");item.putInt("count",1);var output=UUID.randomUUID();s.issueNativeOutput(output,smith,SmithingQuestService.QUEST,item);pending=s.prepareNativeSmithRegistration(UUID.randomUUID(),smith,Map.of(output,item),1);s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));return s;}
 CompoundTag item(UUID source,int damage){var tag=new CompoundTag();tag.putString("id","minecraft:iron_pickaxe");tag.putInt("count",1);var c=new CompoundTag();c.putInt("minecraft:damage",damage);var data=new CompoundTag();var marker=new CompoundTag();marker.putUUID("store",sourceStore);marker.putUUID("id",source);data.put(RepairService.KEY,marker);c.put("minecraft:custom_data",data);tag.put("components",c);return tag;}
 UUID issue(EconomyStore s,UUID owner,UUID source)throws Exception{var consent=UUID.randomUUID();s.authorizeService(consent,owner,smith,ServiceWorkState.SMITH,sourceStore,source,item(source,50));var output=UUID.randomUUID();s.issueServiceOutput(output,smith,consent,item(source,0),1,1);return output;}
 @Test void noCustomerCreditBeforeAtomicPhysicalReturnAndGlobalSourceOnceOnlyAcrossRestartArchive()throws Exception{
  var s=setup();var customer=UUID.randomUUID();var source=UUID.randomUUID();var output=issue(s,customer,source);assertEquals(0,s.serviceWork().jobs(smith,ServiceWorkState.SMITH));var before=s.expectedReceipt(smith);var pending=s.prepareServiceReturn(UUID.randomUUID(),smith,output,item(source,0));
  assertThrows(IllegalStateException.class,()->s.completeServiceQuest(UUID.randomUUID(),smith));assertFalse(s.recoverItem(new EconomyStore.Receipt(s.id(),before)));assertEquals(0,s.itemMailbox(customer).size());
  pending=s.prepareServiceReturn(UUID.randomUUID(),smith,output,item(source,0));assertTrue(s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));assertEquals(pending.sequence(),s.expectedReceipt(smith));assertEquals(1,s.itemMailbox(customer).size());assertEquals(0,s.itemMailbox(smith).size());assertTrue(s.serviceSourceSpent(sourceStore,source));
  assertThrows(IllegalStateException.class,()->s.prepareServiceReturn(UUID.randomUUID(),smith,output,item(source,0)));assertThrows(IllegalStateException.class,()->s.authorizeService(UUID.randomUUID(),customer,smith,ServiceWorkState.SMITH,sourceStore,source,item(source,50)));
  s.archive(smith,"Canonical current-owner service return model");var restored=EconomyStore.open(directory);assertEquals(1,restored.serviceWork().jobs(smith,ServiceWorkState.SMITH));assertEquals(1,restored.itemMailbox(customer).size());assertTrue(restored.serviceSourceSpent(sourceStore,source));assertEquals(s.expectedReceipt(smith),restored.expectedReceipt(smith));
 }
 @Test void threeDistinctJobsAndTwoExplicitCustomersRequiredAndNoRepeatedQuestAward()throws Exception{
  var s=setup();var a=UUID.randomUUID();var b=UUID.randomUUID();long xp=s.professions(smith).track(Profession.BLACKSMITH).xp();
  for(int n=0;n<3;n++){var source=UUID.randomUUID();var out=issue(s,n<2?a:b,source);var pending=s.prepareServiceReturn(UUID.randomUUID(),smith,out,item(source,0));assertTrue(s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));if(n<2)assertThrows(IllegalStateException.class,()->s.completeServiceQuest(UUID.randomUUID(),smith));}
  s.completeServiceQuest(UUID.randomUUID(),smith);assertEquals(xp+300,s.professions(smith).track(Profession.BLACKSMITH).xp());assertEquals(2,s.serviceWork().customers(smith,ServiceWorkState.SMITH));assertThrows(IllegalStateException.class,()->s.completeServiceQuest(UUID.randomUUID(),smith));assertEquals(xp+300,EconomyStore.open(directory).professions(smith).track(Profession.BLACKSMITH).xp());
 }
 @Test void revocationWrongProviderChangedOutputAndAfterRenameRecoveryFailClosed()throws Exception{
  var s=setup();var owner=UUID.randomUUID();var source=UUID.randomUUID();var consent=UUID.randomUUID();s.authorizeService(consent,owner,smith,ServiceWorkState.SMITH,sourceStore,source,item(source,50));assertThrows(IllegalStateException.class,()->s.revokeService(UUID.randomUUID(),UUID.randomUUID(),consent));
  s.revokeService(UUID.randomUUID(),owner,consent);assertThrows(IllegalStateException.class,()->s.issueServiceOutput(UUID.randomUUID(),smith,consent,item(source,0),1,1));var output=issue(s,owner,source);assertThrows(IllegalStateException.class,()->s.prepareServiceReturn(UUID.randomUUID(),UUID.randomUUID(),output,item(source,0)));assertThrows(IllegalStateException.class,()->s.prepareServiceReturn(UUID.randomUUID(),smith,output,item(source,1)));
  var pending=s.prepareServiceReturn(UUID.randomUUID(),smith,output,item(source,0));var bad=EconomyStore.open(directory,(file,data)->{AtomicNbt.write(file,data);throw new IOException("After rename service return uncertainty");});assertThrows(IOException.class,()->bad.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));var restored=EconomyStore.open(directory);assertFalse(restored.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));assertEquals(1,restored.itemMailbox(owner).size());assertEquals(1,restored.serviceWork().jobs(smith,ServiceWorkState.SMITH));assertThrows(IllegalStateException.class,()->restored.prepareServiceReturn(UUID.randomUUID(),smith,output,item(source,0)));
 }
 @Test void exactSourceBindingAndImmutableCopiesRefuseOwnerInference(){var s=new ServiceWorkState();var owner=UUID.randomUUID();var provider=UUID.randomUUID();var source=UUID.randomUUID();var input=item(source,50);assertThrows(IllegalArgumentException.class,()->new ServiceWorkState.Consent(UUID.randomUUID(),owner,provider,ServiceWorkState.SMITH,sourceStore,UUID.randomUUID(),input,true,false));var c=new ServiceWorkState.Consent(UUID.randomUUID(),owner,provider,ServiceWorkState.SMITH,sourceStore,source,input,true,false);s.authorize(c);c.input().putInt("count",99);assertEquals(1,s.consent(c.id()).orElseThrow().input().getInt("count"));assertThrows(IllegalStateException.class,()->s.revoke(c.id(),provider));var copy=s.copy();copy.revoke(c.id(),owner);assertTrue(s.consent(c.id()).orElseThrow().active());}
 CompoundTag enchanted(UUID source,int efficiency){var n=item(source,5);var levels=new CompoundTag();levels.putInt("minecraft:efficiency",efficiency);var ench=new CompoundTag();ench.put("levels",levels);n.getCompound("components").put("minecraft:enchantments",ench);return n;}
 @Test void libraryMaintenanceUsesItsOwnBandPurposeXpAndGlobalSourceOnceAfterArchive()throws Exception{
  var f=new LibraryJourneymanStoreTest();f.directory=directory;var s=f.earnedApprentice();var provider=f.p;var a=UUID.randomUUID();var b=UUID.randomUUID();
  for(int n=0;n<3;n++){var source=UUID.randomUUID();var consent=UUID.randomUUID();var output=UUID.randomUUID();s.authorizeService(consent,n<2?a:b,provider,ServiceWorkState.LIBRARY,sourceStore,source,enchanted(source,2));assertThrows(IllegalStateException.class,()->s.issueServiceOutput(UUID.randomUUID(),provider,consent,enchanted(source,1),1,1));assertThrows(IllegalStateException.class,()->s.issueServiceOutput(UUID.randomUUID(),provider,consent,enchanted(source,2),1,1));s.issueServiceOutput(output,provider,consent,enchanted(source,3),1,2);var pending=s.prepareServiceReturn(UUID.randomUUID(),provider,output,enchanted(source,3));s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence()));assertEquals(0,s.serviceWork().jobs(provider,ServiceWorkState.SMITH));assertTrue(s.serviceSourceSpent(sourceStore,source));assertThrows(IllegalStateException.class,()->s.authorizeService(UUID.randomUUID(),a,provider,ServiceWorkState.LIBRARY,sourceStore,source,enchanted(source,3)));if(n<2)assertThrows(IllegalStateException.class,()->s.completeServiceQuest(UUID.randomUUID(),provider,ServiceWorkState.LIBRARY));}
  s.completeServiceQuest(UUID.randomUUID(),provider,ServiceWorkState.LIBRARY);assertEquals(1000,s.professions(provider).track(Profession.LIBRARIAN).xp());assertThrows(IllegalStateException.class,()->s.completeServiceQuest(UUID.randomUUID(),provider,ServiceWorkState.LIBRARY));s.archive(provider,"Purpose-bound Library native service model");var restored=EconomyStore.open(directory);assertEquals(3,restored.serviceWork().jobs(provider,ServiceWorkState.LIBRARY));assertEquals(2,restored.serviceWork().customers(provider,ServiceWorkState.LIBRARY));assertEquals(2,restored.itemMailbox(a).size());assertEquals(1,restored.itemMailbox(b).size());assertEquals(s.professions(provider),restored.professions(provider));
 }

}
